```c
#include <stdio.h>
#include <string.h>

#define HASH_SIZE 2000003

char visited[HASH_SIZE][101];
int used[HASH_SIZE];
int best;
int initial_len;

int check_and_add(char *s) {
    unsigned long long h = 0;
    for (int i = 0; s[i]; i++) h = h * 131 + s[i];
    int idx = h % HASH_SIZE;
    while (used[idx]) {
        if (strcmp(visited[idx], s) == 0) return 0;
        idx = (idx + 1) % HASH_SIZE;
    }
    used[idx] = 1;
    strcpy(visited[idx], s);
    return 1;
}

void dfs(char *s) {
    int n = strlen(s);
    int removed = initial_len - n;
    if (removed > best) best = removed;
    for (int i = 0; i < n; i++) {
        int can = 0;
        if (i > 0 && s[i-1] == s[i]-1) can = 1;
        if (i < n-1 && s[i+1] == s[i]-1) can = 1;
        if (can) {
            char ns[101];
            memcpy(ns, s, i);
            memcpy(ns+i, s+i+1, n-i);
            ns[n-1] = '\0';
            if (check_and_add(ns)) dfs(ns);
        }
    }
}

int main() {
    int size;
    scanf("%d", &size);
    char str[101];
    scanf("%s", str);
    initial_len = strlen(str);
    best = 0;
    check_and_add(str);
    dfs(str);
    printf("%d\n", best);
    return 0;
}
```

