#include<math.h>

int main()
{
    int l, d, v, g, r;

    scanf("%d%d%d%d%d", &l, &d, &v, &g, &r);

    double t = (double)d / v;
    double cycle = g + r;
    double t_mod = fmod(t, cycle);

    if(t_mod < g)
    {
        printf("%.8f\n", (double)l / v);
    }
    else
    {
        double wait = cycle - t_mod;
        printf("%.8f\n", t + wait + (double)(l - d) / v);
    }

    return 0;
}
```

