```c
#include <stdio.h>

long long gcd(long long a, long long b) {
    while (b) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    long long x, y, a, b;
    scanf("%lld %lld %lld %lld", &x, &y, &a, &b);

    long long g = gcd(x, y);
    long long lcm = x / g * y;

    long long count = b / lcm - (a - 1) / lcm;

