            // prevMask: which cells in previous row are selected
            // coveredMask: which cells in current row are already covered (by prev row selections)

            int fullRow = (1 << C) - 1;

            // For each row, we decide which cells to select
            // A cell is "dominated" if it or one of its neighbors is selected
            // coveredByPrev[mask] = which cells in current row are covered by previous row's selection mask
            // selectedMask covers cells in current row + helps cover next row

            // State: (covered in current row from above)
            // Transition: choose selection for current row
            //   - current row cells covered = covered_from_above | cells_selected | left/right neighbors of selected
            //   - must ensure all cells in prev row are covered (by prev selection or current selection's upward coverage)
            //   - coverage passed down to next row

            // Let me define:
            // dp[r][prevSel][curCovered] = min dominating set size for rows 0..r
            // prevSel: selection mask for row r
            // curCovered: which cells of row r are covered
            // We need curCovered == fullRow when moving past row r

            // Actually standard approach:
            // dp[prevSel][prevCov] after processing row r
            // prevSel = selection in row r
            // prevCov = coverage of row r (must be fullRow before advancing, but row r might get covered by row r+1)

            // Better: dp[r][prevSel][prevRowCovered]
            // When we move to row r+1 with selection nextSel:
            //   - row r gets additional coverage from nextSel (upward)
            //   - prevRowCovered | upCoverage(nextSel) must == fullRow
