            // Helper: given a row selection mask, compute left-right coverage within row
            // and self coverage
            Func<int, int> rowCoverage = (sel) =>
            {
                int cov = sel; // selected cells cover themselves
                cov |= (sel << 1) & fullRow; // right neighbor
                cov |= (sel >> 1) & fullRow; // left neighbor
