using System;
using System.Collections.Generic;

public class Solver
{
    private const int SIEVE_SIZE = 1000010;
    private readonly bool[] isComposite = new bool[SIEVE_SIZE + 1];
    private readonly List<int> primes = new List<int>();

    void Sieve()
    {
        for (int i = 2; (long)i * i <= SIEVE_SIZE; i++)
            if (!isComposite[i])
                for (int j = i * i; j <= SIEVE_SIZE; j += i)
                    isComposite[j] = true;
        for (int i = 2; i <= SIEVE_SIZE; i++)
            if (!isComposite[i])
                primes.Add(i);
    }

    private class SDictionary<TKey, TValue> : Dictionary<TKey, TValue>
    {
        public new TValue this[TKey key]
        {
            get { return ContainsKey(key) ? base[key] : default(TValue); }
            set { base[key] = value; }
        }
    }

    public void Solve()
    {
        Sieve();
        long a = long.Parse(Console.ReadLine().Trim());
        var d = new SDictionary<long, int> { { a, 1 } };
        int ans = 0;

        for (int i = 0; i < primes.Count; i++)
        {
            var toAdd = new List<Tuple<long, int>>();
            var toRemove = new List<long>();

            foreach (var p in d)
            {
                if (p.Key <= primes[i])
                    toRemove.Add(p.Key);
                for (long x = primes[i]; x < p.Key; x *= primes[i])
                {
                    if (p.Key % (x + 1) == 0)
                    {
                        long y = p.Key / (x + 1);
                        if (y == 1)
                            ans += p.Value;
                        else if (y > primes[i])
                            toAdd.Add(Tuple.Create(y, p.Value));
                    }
                    if (x > 2000000000000L)
                        break;
                }
            }

            foreach (var p in toAdd)
                d[p.Item1] += p.Item2;
            foreach (long x in toRemove)
                d.Remove(x);
        }

        foreach (var p in d)
        {
            if (p.Key > SIEVE_SIZE)
            {
                long x = p.Key - 1;
                bool ok = x > 1;
                for (int i = 0; ok && (long)primes[i] * primes[i] <= x; i++)
                    if (x % primes[i] == 0)
                        ok = false;
                if (ok)
                    ans += p.Value;
            }
        }

        Console.WriteLine(ans);
    }

    static void Main()
    {
        new Solver().Solve();
    }
}
