        int hpM = inputArray[0], atkM = inputArray[1], defM = inputArray[2];

        inputArray = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
        int h = inputArray[0], a = inputArray[1], d = inputArray[2];

        long cost = long.MaxValue;

        for (int atk = atkY; atk <= 200; atk++)
        {
            int dmgToM = atk - defM;
            if (dmgToM <= 0) continue;
            long dayM = (hpM + dmgToM - 1) / dmgToM;

            for (int def = defY; def <= 200; def++)
            {
                int dmgToY = Math.Max(0, atkM - def);
                long hpNeeded;
                if (dmgToY == 0)
                    hpNeeded = 1;
                else
                    hpNeeded = dmgToY * dayM + 1;

                long extraHp = Math.Max(0, hpNeeded - hpY);
                long tmp = (long)a * (atk - atkY) + (long)d * (def - defY) + (long)h * extraHp;
                if (tmp < cost) cost = tmp;
            }
        }

        Console.WriteLine(cost);
    }
