namespace CodeForces
{
    class Program
    {
        public static void Main(string[] args)
        {
            long[] input = GetIntArr();
            long x = input[0];
            long y = input[1];
            long l = input[2];
            long r = input[3];

            List<long> xPowers = new List<long>();
            long val = 1;
            while (val <= r)
            {
                xPowers.Add(val);
                if (val > r / x) break; // next would overflow or exceed r
                val *= x;
            }

            List<long> yPowers = new List<long>();
            val = 1;
            while (val <= r)
            {
                yPowers.Add(val);
                if (val > r / y) break;
                val *= y;
            }

            SortedSet<long> unlucky = new SortedSet<long>();
            foreach (long a in xPowers)
            {
                foreach (long b in yPowers)
                {
                    long sum = a + b;
                    if (sum >= l && sum <= r)
                        unlucky.Add(sum);
                    if (sum > r) break; // yPowers is increasing, no need to continue
                }
            }

            List<long> sorted = new List<long>(unlucky);
            sorted.Insert(0, l - 1);
            sorted.Add(r + 1);

            long ans = 0;
            for (int i = 1; i < sorted.Count; i++)
            {
                long gap = sorted[i] - sorted[i - 1] - 1;
                if (gap > ans) ans = gap;
            }

            Console.WriteLine(ans);
        }

