        {
            ulong result = 1;
            baseVal %= mod;
            while (exp > 0)
            {
                if ((exp & 1) == 1)
                {
                    result = result * baseVal % mod;
                }
                baseVal = baseVal * baseVal % mod;
                exp >>= 1;
            }
            return result;
        }

        static void Main(string[] args)
        {
            string[] str = Console.ReadLine().Split();
            ulong x = ulong.Parse(str[0]);
            ulong n = ulong.Parse(str[1]);
            const ulong MOD = 1000000007UL;

            List<ulong> primes = new List<ulong>();
            ulong m = x;
            for (ulong i = 2; i * i <= m; i++)
            {
                if (m % i == 0)
                {
                    primes.Add(i);
                    while (m % i == 0)
                        m /= i;
                }
            }
            if (m > 1)
                primes.Add(m);

            ulong result = 1;
            foreach (ulong p in primes)
            {
                // Legendre's formula: sum of floor(n/p^k) for k=1,2,...
                ulong count = 0;
                ulong pk = p;
                while (pk <= n)
                {
                    count += n / pk;
                    if (pk > n / p) break; // prevent overflow
                    pk *= p;
                }
                result = result * ModPow(p, count, MOD) % MOD;
            }
            Console.WriteLine(result);
        }
    }
}
