```csharp
using System;
using System.Collections.Generic;

public class Program
{
    const long MOD = 1000000007;

    public static void Main(string[] args)
    {
        var parts = Console.ReadLine().Split(' ');
        int N = int.Parse(parts[0]);
        int X = int.Parse(parts[1]);
        int Pos = int.Parse(parts[2]);

        int lessCount = 0, greaterCount = 0;
        int left = 0, right = N;
        while (left < right)
        {
            int middle = (left + right) / 2;
            if (middle == Pos) break;
            else if (middle < Pos) { lessCount++; left = middle + 1; }
            else { greaterCount++; right = middle; }
        }

        if (lessCount > X - 1 || greaterCount > N - X) { Console.WriteLine(0); return; }

        long[] fact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
        long[] inv = new long[N + 1];
        inv[0] = 1; inv[1] = 1;
        for (int i = 2; i <= N; i++) inv[i] = (MOD - MOD/i) * inv[MOD%i] % MOD;
        long[] ifact = new long[N + 1];
        ifact[0] = 1;
        for (int i = 1; i <= N; i++) ifact[i] = ifact[i-1] * inv[i] % MOD;

        long ans = fact[X-1] * ifact[X-1-lessCount] % MOD;
        ans = ans * fact[N-X] % MOD * ifact[N-X-greaterCount] % MOD;
        int rem = N - 1 - lessCount - greaterCount;
        ans = ans * fact[rem] % MOD;
        Console.WriteLine(ans);
    }
}
