using System;

class Program {
    static void Main() {
        string[] ss = Console.ReadLine().Split();
        int n = int.Parse(ss[0]);
        int m = int.Parse(ss[1]);
        if (n > m) { int t = n; n = m; m = t; }

        // Minimum dominating set via column DP
        // State: for each column boundary, track (prevSelected, prevCovered)
        // prevSelected: which cells in prev column are selected
        // prevCovered: which cells in prev column are covered

        int full = (1 << n) - 1;
        int INF = 1000000;
        // dp[prevSel][prevCov] = min selected so far
        int[,] dp = new int[1<<n, 1<<n];
        for (int i = 0; i < (1<<n); i++)
            for (int j = 0; j < (1<<n); j++)
                dp[i,j] = INF;
        dp[0, 0] = 0;

        for (int col = 0; col < m; col++) {
            int[,] ndp = new int[1<<n, 1<<n];
            for (int i = 0; i < (1<<n); i++)
                for (int j = 0; j < (1<<n); j++)
                    ndp[i,j] = INF;

            for (int prevSel = 0; prevSel < (1<<n); prevSel++)
            for (int prevCov = 0; prevCov < (1<<n); prevCov++) {
                if (dp[prevSel, prevCov] == INF) continue;
                int val = dp[prevSel, prevCov];
                // Try all selections for current column
                for (int curSel = 0; curSel < (1<<n); curSel++) {
                    // Coverage from curSel: cells covered in cur col, and spillover to prev and next
                    int covCur = curSel; // selected covers itself
                    covCur |= (curSel << 1) & full; // covers cell below
                    covCur |= (curSel >> 1); // covers cell above
                    covCur |= prevSel; // prev column selected covers current column
                    int covPrev = prevCov | curSel; // current selection covers prev column cells
                    // vertical neighbors within prevSel
                    covPrev |= (prevSel << 1) & full;
                    covPrev |= (prevSel >> 1);
                    // Check prev column fully covered (if not first col, or col>0)
                    if (col > 0 && covPrev != full) continue;
                    if (col == 0) covPrev = 0; // don't check
                    else if (covPrev != full) continue;

                    int newVal = val + CountBits(curSel);
                    if (ndp[curSel, covCur] > newVal)
                        ndp[curSel, covCur] = newVal;
                }
            }
            dp = ndp;
        }

        int best = INF;
        for (int s = 0; s < (1<<n); s++)
            if (dp[s, full] < best) best = dp[s, full];

        Console.WriteLine(n * m - best);
    }

    static int CountBits(int x) {
        int c = 0; while (x > 0) { c += x & 1; x >>= 1; } return c;
    }
