    cin >> x1 >> y1 >> x2 >> y2 >> x >> y;

    long long dx = x2 - x1;
    long long dy = y2 - y1;

    if (dx % x != 0 || dy % y != 0) { cout << "NO" << endl; return 0; }

    long long px = dx / x;
    long long py = dy / y;

    if (abs(px) % 2 == abs(py) % 2) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}
