    ll n, m;
    cin >> n >> m;
    vector<ll> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int half1 = n / 2;
    int half2 = n - half1;

    // Enumerate all subset sums mod m for first half
    vector<ll> v1, v2;
    for (int mask = 0; mask < (1 << half1); mask++) {
        ll s = 0;
        for (int i = 0; i < half1; i++)
            if (mask >> i & 1) s = (s + a[i]) % m;
        v1.push_back(s);
    }

    // Enumerate all subset sums mod m for second half
    for (int mask = 0; mask < (1 << half2); mask++) {
        ll s = 0;
        for (int i = 0; i < half2; i++)
            if (mask >> i & 1) s = (s + a[half1 + i]) % m;
        v2.push_back(s);
