        // Best s2 without overflow: largest s2 < m - s1
        ll need = m - s1; // s2 < need means s1+s2 < m
        auto it = lower_bound(v2.begin(), v2.end(), need);
        // largest s2 < need
        if (it != v2.begin()) {
            --it;
            ans = max(ans, (s1 + *it) % m);
