```cpp
#include<bits/stdc++.h>
using namespace std;

map<string,int> memo;

int solve(const string& s){
    auto it = memo.find(s);
    if(it != memo.end()) return it->second;

    int n = s.size();
    int best = 0;
    for(int i = 0; i < n; i++){
        bool canRemove = false;
        if(i > 0 && s[i-1] == s[i]-1) canRemove = true;
        if(i < n-1 && s[i+1] == s[i]-1) canRemove = true;
        if(!canRemove) continue;
        string ns = s.substr(0,i) + s.substr(i+1);
        best = max(best, 1 + solve(ns));
    }
    memo[s] = best;
    return best;
}

