    public int[][] pow(int[][] A, int N){
      if (N == 1){
        int[][] ret = A.clone();
        return ret;
      }

      if (N % 2 == 1) 
        return mul(A, pow(A, N-1));
      else
        return pow(mul(A, A), N/2);      
    }

    public int[][] mul(int[][] A, int[][] B){
      int[][] ret = new int[A.length][A[0].length];
      for(int i = 0; i < A.length; i++){
